<?php

/*
Время намаза
https://namaz.muftyat.kz/kk/namaz/api/
*/

class PrayTime
{
	public $url;
	
	public function __construct()
	{
		$this->url = 'https://api.muftyat.kz/';
	}
	
	public function getDay($id = 7)
	{
		$output = [];
		if ($data = $this->getYear($id)) {
			$today = date('Y-m-d');
			$output['year'] = $data['year'];
			$output['city'] = $data['city'];
			$output['region'] = $data['region'];
			$output['lat'] = $data['lat'];
			$output['lng'] = $data['lng'];
			foreach ($data['result'] as $v) {
				if ($v['Date'] == $today) {
					$output['result'] = $v;
				}
			}
		}
		return $output;
	}
	
	public function getMonth($id = 7, $month = '', $year = '')
	{
		if (!$year) $year = date('Y');
		$output = [];
		if ($data = $this->getYear($id, $year)) {
			if (!$month) {
				$today = date('Y-m-d');
				$month = $this->getNumberMonth($today);
			}
			$output['year'] = $year;
			$output['city'] = $data['city'];
			$output['region'] = $data['region'];
			$output['lat'] = $data['lat'];
			$output['lng'] = $data['lng'];
			$i = 0;
			foreach ($data['result'] as $v) {
				if ($this->getNumberMonth($v['Date']) == $month) {
					$output['result'][$i] = $v;
					$i++;
				}
			}
		}
		return $output;
	}
	
	public function getYear($id = 7, $year = '')
	{
		$output = [];
		$city = $this->getCities($id);
		if (!$year) $year = date('Y');
		$data = $this->getApi("{$this->url}prayer-times/{$year}/{$city['lat']}/{$city['lng']}");
		if ($data) {
			$hijri = $this->gregorianToHijri();
			$output['year'] = $year;
			$output['city'] = $city['title'];
			$output['region'] = $city['region'];
			$output['lat'] = $city['lat'];
			$output['lng'] = $city['lng'];
			foreach ($data['result'] as $k => $v) {
				$output['result'][$k]['fajr'] = $v['fajr'];
				$output['result'][$k]['imsak'] = $v['imsak'];
				$output['result'][$k]['sunrise'] = $v['sunrise'];
				$output['result'][$k]['dhuhr'] = $v['dhuhr'];
				$output['result'][$k]['asr'] = $v['asr'];
				$output['result'][$k]['sunset'] = $v['sunset'];
				$output['result'][$k]['maghrib'] = $v['maghrib'];
				$output['result'][$k]['isha'] = $v['isha'];
				$output['result'][$k]['midnight'] = $v['midnight'];
				$output['result'][$k]['tahajjud'] = $this->tahajjud($v['Date'], $v['fajr'], $v['maghrib']);
				$output['result'][$k]['Date'] = $v['Date'];
				$output['result'][$k]['Date_hijri'] = $hijri;
				$output['result'][$k]['day'] = $this->getNumberDay($v['Date']);
				$output['result'][$k]['week'] = $this->getWeeks($v['Date']);
				$output['result'][$k]['month'] = $this->getMonths($this->getNumberMonth($v['Date']));
				$output['result'][$k]['month_hijri'] = $this->getMonthsHijri($this->getNumberMonth($hijri));
			}
		}
		return $output;
	}
	
	private function getWeeks($date = '')
	{
		$array = [
			1 => ['short' => 'Пн', 'ru' => 'Понедельник', 'kz' => 'Дүйсенбі', 'en' => 'Monday'],
			['short' => 'Вт', 'ru' => 'Вторник', 'kz' => 'Сейсенбі', 'en' => 'Tuesday'],
			['short' => 'Ср', 'ru' => 'Среда', 'kz' => 'Сәрсенбі', 'en' => 'Wednesday'],
			['short' => 'Чт', 'ru' => 'Четверг', 'kz' => 'Бейсенбі', 'en' => 'Thursday'],
			['short' => 'Пт', 'ru' => 'Пятница', 'kz' => 'Жұма', 'en' => 'Friday'],
			['short' => 'Сб', 'ru' => 'Суббота', 'kz' => 'Сенбі', 'en' => 'Saturday'],
			['short' => 'Вс', 'ru' => 'Воскресенье', 'kz' => 'Жексенбі', 'en' => 'Sunday'],
		];
		if ($date) {
			$weekNum = date('N', strtotime($date));
			$result = [];
			foreach ($array as $k => $v) {
				if ($k == $weekNum) {
					$result['short'] = $v['short'];
					$result['ru'] = $v['ru'];
					$result['kz'] = $v['kz'];
					$result['en'] = $v['en'];
					$result['num'] = $k;
				}
			}
		} else {
			$result = $array;
		}
		return $result;
	}
	
	private function getMonths($month = '')
	{
		$array = [
			1 => ['ru' => 'Январь', 'kz' => 'Қаңтар', 'en' => 'January'],
			['ru' => 'Февраль', 'kz' => 'Ақпан', 'en' => 'February'],
			['ru' => 'Март', 'kz' => 'Наурыз', 'en' => 'March'],
			['ru' => 'Апрель', 'kz' => 'Сәуір', 'en' => 'April'],
			['ru' => 'Май', 'kz' => 'Мамыр', 'en' => 'May'],
			['ru' => 'Июнь', 'kz' => 'Маусым', 'en' => 'June'],
			['ru' => 'Июль', 'kz' => 'Шілде', 'en' => 'July'],
			['ru' => 'Август', 'kz' => 'Тамыз', 'en' => 'August'],
			['ru' => 'Сентябрь', 'kz' => 'Қыркүйек', 'en' => 'September'],
			['ru' => 'Октябрь', 'kz' => 'Қазан', 'en' => 'October'],
			['ru' => 'Ноябрь', 'kz' => 'Қараша', 'en' => 'November'],
			['ru' => 'Декабрь', 'kz' => 'Желтоқсан', 'en' => 'December'],
		];
		if ($month) {
			$result = [];
			foreach ($array as $k => $v) {
				if ($month == $k) $result = $v;
			}
			$result['num'] = $month;
		} else {
			$result = $array;
		}
		return $result;
	}
	
	private function gregorianToHijri($timestamp = null)
	{
		if (!$timestamp) $timestamp = time();
		$jd = gregoriantojd(
			date('m', $timestamp),
			date('d', $timestamp),
			date('Y', $timestamp)
		);
		$l = $jd - 1948440 + 10632;
		$n = intdiv($l - 1, 10631);
		$l = $l - 10631 * $n + 354;
		$j = (int)((10985 - $l) / 5316) * (int)(50 * $l / 17719)
		   + (int)($l / 5670) * (int)(43 * $l / 15238);
		$l = $l - (int)((30 - $j) / 15) * (int)(17719 * $j / 50)
		   - (int)($j / 16) * (int)(15238 * $j / 43) + 29;
		$month = (int)(24 * $l / 709);
		$day   = $l - (int)(709 * $month / 24);
		$year  = 30 * $n + $j - 30;
		return $year . '-' . $month . '-' . $day;
	}
	
	private function getMonthsHijri($month = '')
	{
		$array = [
			1  => ['ru' => 'Мухаррам', 'kz' => 'Мухаррам', 'en' => 'Muharram'],
			['ru' => 'Сафар', 'kz' => 'Сафар', 'en' => 'Safar'],
			['ru' => 'Раби аль-авваль', 'kz' => 'Рабиул-әууәл', 'en' => 'Rabi al-Awwal'],
			['ru' => 'Раби ас-сани', 'kz' => 'Рабиус-сани', 'en' => 'Rabi al-Thani'],
			['ru' => 'Джумада аль-уля', 'kz' => 'Жұмада әл-әууәл', 'en' => 'Jumada al-Awwal'],
			['ru' => 'Джумада ас-сани', 'kz' => 'Жұмада ас-сани', 'en' => 'Jumada al-Thani'],
			['ru' => 'Раджаб', 'kz' => 'Рәжәп', 'en' => 'Rajab'],
			['ru' => 'Шаабан', 'kz' => 'Шағбан', 'en' => 'Sha‘ban'],
			['ru' => 'Рамадан', 'kz' => 'Рамазан', 'en' => 'Ramadan'],
			['ru' => 'Шавваль', 'kz' => 'Шәууәл', 'en' => 'Shawwal'],
			['ru' => 'Зу-ль-када', 'kz' => 'Зул-қада', 'en' => 'Dhul-Qadah'],
			['ru' => 'Зу-ль-хиджа', 'kz' => 'Зул-хижжа', 'en' => 'Dhul-Hijjah'],
		];
		if ($month) {
			$result = [];
			foreach ($array as $k => $v) {
				if ($month == $k) $result = $v;
			}
			$result['num'] = $month;
		} else {
			$result = $array;
		}
		return $result;
	}

	private function getNumberMonth($date)
	{
		$month = explode('-', $date);
		return ltrim($month[1], '0');
	}
	
	private function getNumberDay($date)
	{
		$month = explode('-', $date);
		return ltrim($month[2], '0');
	}
	
	private function tahajjud($date, $fajr, $maghrib, $timezone = 5)
	{
		$tzSign   = $timezone >= 0 ? '+' : '-';
		$tzOffset = sprintf('%s%02d:00', $tzSign, abs($timezone));
		$tz = new DateTimeZone($tzOffset);
		$start = new DateTime("$date $maghrib", $tz);
		$endDate = (new DateTime($date, $tz))
			->modify('+1 day')
			->format('Y-m-d');
		$end = new DateTime("$endDate $fajr", $tz);
		$intervalSeconds = $end->getTimestamp() - $start->getTimestamp();
		if ($intervalSeconds <= 0) {
			return '';
		}
		$twoThirds = (int) floor($intervalSeconds * 2 / 3);
		$tahajjudTime = (clone $start)->modify("+{$twoThirds} seconds");
		return $tahajjudTime->format('H:i');
	}
	
